async def execute(limit=20):
    """Aktiva Zabbix-problem."""
    cfg = env['ai.zabbix.config'].search([('active', '=', True)], limit=1)
    if not cfg:
        return 'Ingen aktiv ai.zabbix.config hittades'
    try:
        problems = cfg._zabbix_problems(limit=int(limit))
        return json.dumps(problems, ensure_ascii=False, default=str)
    except Exception as e:
        return 'Zabbix-fel: %s' % e

